svg.script:
(function() {
  const svg = document.documentElement;
  const frames = Array.from(svg.querySelectorAll('.frame'));
  const frameCount = frames.length;
  let framePos = 0;
  let currentFrame = 0;
  let fps = 0; // frames per second. Positive = forward, negative = reverse.
  let lastTs = null;
  let paused = false;

  function mod(n, m) { return ((n % m) + m) % m; }

  function render() {
    const idx = mod(Math.floor(framePos), frameCount);
    if (idx === currentFrame) return idx;
    frames[currentFrame].setAttribute('visibility', 'hidden');
    frames[idx].setAttribute('visibility', 'visible');
    currentFrame = idx;
    svg.setAttribute('data-frame', String(idx));
    return idx;
  }

  function forceRender() {
    const idx = mod(Math.floor(framePos), frameCount);
    frames.forEach((f, i) => f.setAttribute('visibility', i === idx ? 'visible' : 'hidden'));
    currentFrame = idx;
    svg.setAttribute('data-frame', String(idx));
    return idx;
  }

  function tick(ts) {
    if (lastTs == null) lastTs = ts;
    const dt = Math.min((ts - lastTs) / 1000, 0.1);
    lastTs = ts;
    if (!paused && fps !== 0) {
      framePos = mod(framePos + fps * dt, frameCount);
      render();
    }
    requestAnimationFrame(tick);
  }

  function setFrame(index) {
    framePos = mod(Number(index) || 0, frameCount);
    return forceRender();
  }

  function nextFrame(step) {
    framePos = mod(framePos + (Number(step) || 1), frameCount);
    return forceRender();
  }

  // Normalized speed: 0..1 is gentle to fast, but any value is accepted.
  // 1.0 normalized speed = 12 frames per second.
  function setSpinSpeed(speed) {
    const s = Number(speed) || 0;
    fps = s * 12;
    svg.setAttribute('data-fps', String(fps));
    return fps;
  }

  // Direct frames-per-second control.
  function setFrameRate(value) {
    fps = Number(value) || 0;
    svg.setAttribute('data-fps', String(fps));
    return fps;
  }

  // 1 full rotation moves through the whole 10-frame cycle one time.
  function applySpin(rotations) {
    const r = Number(rotations) || 0;
    framePos = mod(framePos + r * frameCount, frameCount);
    return forceRender();
  }

  function setJoystickRPM(rpm) {
    const r = Number(rpm) || 0;
    fps = (r / 60) * frameCount;
    svg.setAttribute('data-fps', String(fps));
    return fps;
  }

  function pause() { paused = true; return true; }
  function play() { paused = false; return true; }
  function getState() {
    return {
      frame: currentFrame,
      frameCount,
      fps,
      paused,
      width: 750,
      height: 250
    };
  }

  window.CookingMachine = {
    setSpinSpeed,
    setFrameRate,
    setJoystickRPM,
    applySpin,
    setFrame,
    nextFrame,
    pause,
    play,
    getState
  };

  window.addEventListener('message', (event) => {
    const d = event.data || {};
    switch (d.type) {
      case 'cooking-machine:setSpinSpeed': setSpinSpeed(d.speed); break;
      case 'cooking-machine:setFrameRate': setFrameRate(d.fps); break;
      case 'cooking-machine:setJoystickRPM': setJoystickRPM(d.rpm); break;
      case 'cooking-machine:applySpin': applySpin(d.rotations); break;
      case 'cooking-machine:setFrame': setFrame(d.frame); break;
      case 'cooking-machine:nextFrame': nextFrame(d.step); break;
      case 'cooking-machine:pause': pause(); break;
      case 'cooking-machine:play': play(); break;
    }
  });

  forceRender();
  requestAnimationFrame(tick);
})();
